"""
test_agent.py
=============
The Test Agent for the robot navigation project.

The Test Agent is responsible for creating the tests of the navigation logic,
based on:

* the requirements brief / validated requirements (Analyst Agent),
* the plan created by the Planner Agent,
* the ``decide_next_move`` function generated by the Developer Agent.

The generated tests must cover **all possible scenarios** and prove that
``decide_next_move`` behaves as the brief requires (safe, goal directed, stops
when no safe direction is available). The tests are written to
``generated/test_navigation_logic.py`` so that the whole pipeline can also run
them with pytest.

Public API:
    SYSTEM_PROMPT
    build_test_prompt(requirements, plan, navigation_code) -> str
    validate_test_code(code)                              -> str
    build_fallback_test_code(requirements=None, plan=None) -> str
    run_test_agent(requirements, plan, navigation_code)    -> str  (test code)
    run_generated_tests(test_path)                         -> (dict, output)
    generate_and_run_tests(...)                            -> dict (full result)
"""

import json
import os
import re
import subprocess
import sys

from openai import OpenAI

MODEL = os.getenv("QWEN_MODEL", "qwen-plus")
BASE_URL = "https://dashscope.aliyuncs.com/compatible-mode/v1"
MAX_ATTEMPTS = 3

HERE = os.path.dirname(os.path.abspath(__file__))
GENERATED_DIR = os.path.join(HERE, "generated")
TEST_PATH = os.path.join(GENERATED_DIR, "test_navigation_logic.py")
# the implementation the generated tests import (generated.navigation_logic)
DEFAULT_TARGET_PATH = os.path.join(GENERATED_DIR, "navigation_logic.py")
GENERATED_DIR_REL = "generated"

# The canonical perception-state contract of the whole project.
STATE_KEYS = (
    "blocked_front",
    "blocked_left",
    "blocked_right",
    "goal_front",
    "goal_left",
    "goal_right",
)
VALID_ACTIONS = ("FORWARD", "LEFT", "RIGHT", "STOP")

# Keywords the generated test code must contain to be accepted.
REQUIRED_IMPORTS = ("import",)
REQUIRED_REFERENCES = ("decide_next_move",)
REQUIRED_ASSERTIONS = ("assert", "assertEqual", "pytest.raises")

SYSTEM_PROMPT = """You are a test engineer (the "Test Agent") for a mobile robot navigation system.

ROLE:
You write the automated tests for the navigation function decide_next_move(state)
that the Developer Agent implemented from the navigation plan.

INPUT:
- The validated requirements produced by the Analyst Agent.
- The navigation plan produced by the Planner Agent.
- The source code of the generated decide_next_move function.

FUNCTION UNDER TEST:
decide_next_move(state) receives ONE dictionary and returns ONE string action.
The dictionary contains exactly these six boolean keys (all always present, all booleans):
- "blocked_front": True when the path in front of the robot is blocked.
- "blocked_left":  True when the path to the left is blocked.
- "blocked_right": True when the path to the right is blocked.
- "goal_front":    True when the goal lies ahead of the robot.
- "goal_left":     True when the goal lies to the left of the robot.
- "goal_right":    True when the goal lies to the right of the robot.
The returned string is exactly one of: "FORWARD", "LEFT", "RIGHT", "STOP".

REQUIRED BEHAVIOUR (from the requirements and the plan):
1. The robot must NEVER move into a blocked direction: no "FORWARD" while
   blocked_front, no "LEFT" while blocked_left, no "RIGHT" while blocked_right.
2. The robot prefers moving toward its goal whenever that direction is safe:
   goal_front and not blocked_front -> "FORWARD";
   goal_left  and not blocked_left  -> "LEFT";
   goal_right and not blocked_right -> "RIGHT".
3. If no goal direction is safe, any safe direction may be taken
   (reference priority: FORWARD, then LEFT, then RIGHT).
4. If no safe direction is available at all, the robot must return "STOP".

REQUIRED TEST COVERAGE:
- All 2**6 = 64 combinations of the six boolean keys, checking the safety rule
  (never a blocked direction) and rule 4 (all blocked -> "STOP").
- Every goal-aligned safe case: goal_front/LEFT/RIGHT -> FORWARD/LEFT/RIGHT.
- Goal direction blocked -> a safe alternative is returned.
- Boundary states: all directions blocked, nothing blocked, every single
  direction blocked, several goal flags set at once.
- Determinism: calling the function twice with the same state returns the same action.
- Valid output: the returned value is always one of FORWARD, LEFT, RIGHT, STOP.
- The function does not mutate the state dictionary it receives.

OUTPUT FORMAT (strict):
- Return ONLY executable Python 3 code for a pytest-style test module.
- No markdown, no code fences, no comments about how the code was produced,
  no explanation before or after the code.
- Import the function under test exactly like this (the tests are executed with
  the project root as the working directory):
      from generated.navigation_logic import decide_next_move
- Use module level constants, helper functions and `assert` statements
  (plain pytest style, no unittest classes are required).
- The module must be importable and every test must run on its own.
"""


# ---------------------------------------------------------------------------
# Prompt construction
# ---------------------------------------------------------------------------
def build_test_prompt(requirements, plan, navigation_code):
    """Build the user prompt sent to the Test Agent.

    It contains the requirements, the plan and the generated navigation code so
    the Test Agent can test the very implementation it receives.
    """
    requirements_text = json.dumps(requirements, indent=2, ensure_ascii=False, default=str)
    plan_text = json.dumps(plan, indent=2, ensure_ascii=False, default=str)
    return (
        "REQUIREMENTS (from the Analyst Agent):\n"
        "%s\n\n"
        "PLAN (from the Planner Agent):\n"
        "%s\n\n"
        "GENERATED NAVIGATION LOGIC (from the Developer Agent):\n"
        "```python\n%s\n```\n\n"
        "Write the pytest-style test module for decide_next_move(state) exactly as "
        "specified in your instructions. Cover all 64 state combinations, all "
        "goal-directed cases and all blocked cases. Return only the Python code."
        % (requirements_text, plan_text, navigation_code)
    )


# ---------------------------------------------------------------------------
# Validation
# ---------------------------------------------------------------------------
def validate_test_code(code):
    """Validate the test code produced by the Test Agent.

    The code must be a non-empty string, must not contain markdown code fences
    and must contain the necessary import statements, a reference to the
    function under test and test assertions. Returns the code or raises
    ValueError describing the problem.
    """
    if not isinstance(code, str):
        raise ValueError(
            "Test code must be a string, got %s." % type(code).__name__
        )
    if not code.strip():
        raise ValueError("Test code must be a non-empty string.")

    stripped = code.strip()
    if "```" in stripped:
        raise ValueError("Test code must not contain markdown code fences (```).")

    lowered = stripped.lower()
    for forbidden in ("here is the test", "here's the test", "explanation:"):
        if lowered.startswith(forbidden):
            raise ValueError("Test code must not contain explanatory prose.")

    for keyword in REQUIRED_IMPORTS:
        if keyword not in stripped:
            raise ValueError("Test code must contain an %r statement." % keyword)

    if not any(reference in stripped for reference in REQUIRED_REFERENCES):
        raise ValueError(
            "Test code must reference the function under test %s."
            % ", ".join(REQUIRED_REFERENCES)
        )

    if "generated" not in stripped:
        raise ValueError(
            "Test code must import the navigation logic from the 'generated' package."
        )

    if not any(assertion in stripped for assertion in REQUIRED_ASSERTIONS):
        raise ValueError(
            "Test code must contain test assertions (%s)."
            % ", ".join(REQUIRED_ASSERTIONS)
        )

    try:
        compile(stripped, "<test_agent_output>", "exec")
    except SyntaxError as error:
        raise ValueError("Test code is not valid Python: %s" % error)

    return stripped


# ---------------------------------------------------------------------------
# Deterministic fallback test module
# ---------------------------------------------------------------------------
def build_fallback_test_code(requirements=None, plan=None):
    """Return a self-contained pytest module covering all 64 scenarios.

    This is used when the LLM is unavailable (missing API key or no network),
    so that the pipeline still produces and runs a real test suite.
    """
    return '''"""
test_navigation_logic.py
========================
Auto-generated tests for decide_next_move(state).

Generated by test_agent.py as a deterministic fallback: it covers all 64
possible perception states, the goal-directed preference rules, the safety
rule (never move into a blocked direction) and the stop rule.
"""

import itertools
import os
import sys

import pytest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from generated.navigation_logic import decide_next_move

STATE_KEYS = (
    "blocked_front",
    "blocked_left",
    "blocked_right",
    "goal_front",
    "goal_left",
    "goal_right",
)

VALID_ACTIONS = {"FORWARD", "LEFT", "RIGHT", "STOP"}

BLOCKED_KEY_FOR_ACTION = {
    "FORWARD": "blocked_front",
    "LEFT": "blocked_left",
    "RIGHT": "blocked_right",
}


def make_state(blocked_front, blocked_left, blocked_right,
               goal_front, goal_left, goal_right):
    return {
        "blocked_front": bool(blocked_front),
        "blocked_left": bool(blocked_left),
        "blocked_right": bool(blocked_right),
        "goal_front": bool(goal_front),
        "goal_left": bool(goal_left),
        "goal_right": bool(goal_right),
    }


def all_states():
    for combo in itertools.product([False, True], repeat=6):
        yield make_state(*combo)


def reference_action(state):
    """Reference policy used to compute the expected action."""
    if state["goal_front"] and not state["blocked_front"]:
        return "FORWARD"
    if state["goal_left"] and not state["blocked_left"]:
        return "LEFT"
    if state["goal_right"] and not state["blocked_right"]:
        return "RIGHT"
    if not state["blocked_front"]:
        return "FORWARD"
    if not state["blocked_left"]:
        return "LEFT"
    if not state["blocked_right"]:
        return "RIGHT"
    return "STOP"


def is_safe(state, action):
    """The robot must never move into a blocked direction."""
    blocked_key = BLOCKED_KEY_FOR_ACTION.get(action)
    if blocked_key is None:
        return action == "STOP"
    return not state[blocked_key]


def test_returns_only_valid_actions():
    for state in all_states():
        assert decide_next_move(state) in VALID_ACTIONS


def test_never_moves_into_a_blocked_direction():
    for state in all_states():
        action = decide_next_move(state)
        assert is_safe(state, action), (state, action)


def test_all_directions_blocked_returns_stop():
    for goal_front, goal_left, goal_right in itertools.product([False, True], repeat=3):
        state = make_state(True, True, True, goal_front, goal_left, goal_right)
        assert decide_next_move(state) == "STOP"


def test_matches_reference_policy_for_all_64_scenarios():
    for state in all_states():
        assert decide_next_move(state) == reference_action(state), state


def test_goal_front_safe_returns_forward():
    state = make_state(False, False, False, True, False, False)
    assert decide_next_move(state) == "FORWARD"


def test_goal_left_safe_returns_left():
    state = make_state(True, False, True, False, True, False)
    assert decide_next_move(state) == "LEFT"


def test_goal_right_safe_returns_right():
    state = make_state(True, True, False, False, False, True)
    assert decide_next_move(state) == "RIGHT"


def test_goal_direction_blocked_falls_back_to_safe_direction():
    state = make_state(True, False, True, True, False, False)
    assert decide_next_move(state) in {"LEFT", "RIGHT"}
    assert is_safe(state, decide_next_move(state))


def test_no_goal_direction_prefers_a_safe_direction():
    state = make_state(True, False, False, False, False, False)
    assert decide_next_move(state) == "LEFT"


def test_everything_free_and_no_goal_moves_forward():
    state = make_state(False, False, False, False, False, False)
    assert decide_next_move(state) == "FORWARD"


@pytest.mark.parametrize("blocked_key", ["blocked_front", "blocked_left", "blocked_right"])
def test_single_blocked_direction_is_respected(blocked_key):
    for goal_key in ["goal_front", "goal_left", "goal_right"]:
        state = make_state(False, False, False, False, False, False)
        state[blocked_key] = True
        state[goal_key] = True
        action = decide_next_move(state)
        assert action in VALID_ACTIONS
        assert is_safe(state, action)


def test_several_goal_flags_set_at_once_is_safe():
    state = make_state(False, False, False, True, True, True)
    action = decide_next_move(state)
    assert action in {"FORWARD", "LEFT", "RIGHT"}
    assert is_safe(state, action)


def test_deterministic_for_repeated_calls():
    for state in all_states():
        assert decide_next_move(dict(state)) == decide_next_move(dict(state))


def test_state_dictionary_is_not_mutated():
    for state in all_states():
        original = dict(state)
        decide_next_move(state)
        assert state == original
'''


# ---------------------------------------------------------------------------
# Test execution
# ---------------------------------------------------------------------------
def run_generated_tests(test_path=None):
    """Execute the generated test module with pytest.

    Returns ``(results, output)`` where ``results`` holds the parsed pytest
    summary and ``output`` is the captured console output.
    """
    if test_path is None:
        test_path = TEST_PATH
    test_path = os.path.abspath(test_path)

    if not os.path.exists(test_path):
        raise FileNotFoundError("Generated test file not found at %s" % test_path)

    command = [
        sys.executable, "-m", "pytest", test_path,
        "-v", "--no-header", "-p", "no:cacheprovider",
    ]
    completed = subprocess.run(
        command,
        cwd=HERE,
        capture_output=True,
        text=True,
    )
    output = (completed.stdout or "") + (completed.stderr or "")

    # Count the per-test outcome lines of the verbose report. The summary line
    # cannot be parsed positionally because pytest prints the outcomes in a
    # different order depending on which of them are present
    # (e.g. "8 failed, 8 passed in 0.18s").
    outcome_pattern = re.compile(r"\b(PASSED|FAILED|ERROR)\b")
    passed = failed = errors = 0
    in_summary = False
    for line in output.splitlines():
        if line.startswith("="):
            in_summary = "short test summary" in line
            continue
        if in_summary or "::" not in line:
            continue  # the short summary repeats the failures already counted
        match = outcome_pattern.search(line)
        if not match:
            continue
        outcome = match.group(1)
        if outcome == "PASSED":
            passed += 1
        elif outcome == "FAILED":
            failed += 1
        else:
            errors += 1

    if passed == 0 and failed == 0 and errors == 0:
        # fall back to the summary counts when no per-test outcome was printed
        for keyword, counter in (("passed", "passed"), ("failed", "failed"),
                                 ("error", "errors")):
            match = re.search(r"(\d+)\s+%s" % keyword, output)
            if match:
                value = int(match.group(1))
                if counter == "passed":
                    passed = value
                elif counter == "failed":
                    failed = value
                else:
                    errors += value

    results = {
        "test_file": os.path.relpath(test_path, HERE),
        "returncode": completed.returncode,
        "passed": passed,
        "failed": failed,
        "errors": errors,
        "status": "PASSED" if completed.returncode == 0 else "FAILED",
        "command": " ".join(command),
    }
    return results, output


def run_test_agent(requirements, plan, navigation_code, client=None, test_path=None):
    """Run the Test Agent and return the *validated* test code.

    The code is written to ``generated/test_navigation_logic.py`` so that the
    orchestrator (main.py) can execute it. If the LLM is unavailable, a
    deterministic test module covering all 64 scenarios is used instead.
    """
    if test_path is None:
        test_path = TEST_PATH
    test_path = os.path.abspath(test_path)

    # The tests import generated.navigation_logic, so the implementation they
    # were written for must be the one that is actually importable. This keeps
    # the generated tests and the navigation logic in sync in every run.
    os.makedirs(GENERATED_DIR, exist_ok=True)
    with open(DEFAULT_TARGET_PATH, "w", encoding="utf-8") as handle:
        handle.write(navigation_code)
        if not navigation_code.endswith("\n"):
            handle.write("\n")

    prompt = build_test_prompt(requirements, plan, navigation_code)
    attempts = []

    try:
        llm_client = client if client is not None else get_client()
    except Exception as error:  # no key configured -> deterministic fallback
        attempts.append("LLM unavailable: %s" % error)
        llm_client = None

    code = None
    if llm_client is not None:
        for attempt in range(1, MAX_ATTEMPTS + 1):
            response = llm_client.chat.completions.create(
                model=MODEL,
                messages=[
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": prompt},
                ],
                temperature=0.0,
            )
            raw_text = response.choices[0].message.content
            try:
                code = validate_test_code(_strip_code_fences(raw_text))
                break
            except (ValueError, AttributeError) as error:
                attempts.append("attempt %d: %s" % (attempt, error))
                print("[test_agent] attempt %d failed: %s" % (attempt, error))

    if code is None:
        if llm_client is not None:
            print("[test_agent] falling back to the deterministic test module")
        code = validate_test_code(build_fallback_test_code(requirements, plan))

    os.makedirs(os.path.dirname(test_path), exist_ok=True)
    with open(test_path, "w", encoding="utf-8") as handle:
        handle.write(code)
        if not code.endswith("\n"):
            handle.write("\n")

    return code


def generate_and_run_tests(requirements, plan, navigation_code, client=None,
                           test_path=None):
    """Convenience wrapper used by the orchestrator: generate AND run the tests.

    Returns a dict with the generated code, the file path, the pytest results
    and the captured pytest output.
    """
    code = run_test_agent(
        requirements, plan, navigation_code, client=client, test_path=test_path
    )
    results, output = run_generated_tests(test_path)
    return {
        "test_code": code,
        "test_path": os.path.relpath(os.path.abspath(test_path or TEST_PATH), HERE),
        "results": results,
        "output": output,
    }


# ---------------------------------------------------------------------------
# Helpers (same style as the Analyst / Planner / Developer agents)
# ---------------------------------------------------------------------------
def _strip_code_fences(text):
    """Remove markdown code fences if the model wrapped the code in them."""
    text = (text or "").strip()
    fence = re.search(r"```(?:python)?\s*(.*?)```", text, re.DOTALL | re.IGNORECASE)
    if fence:
        return fence.group(1).strip()
    return text


def _load_env_file():
    env_path = os.path.join(HERE, ".env")
    if not os.path.exists(env_path):
        return
    with open(env_path, "r", encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            key, _, value = line.partition("=")
            value = value.strip().strip('"').strip("'")
            os.environ.setdefault(key.strip(), value)


def get_client():
    _load_env_file()
    api_key = os.getenv("DASHSCOPE_API_KEY")
    if not api_key:
        raise RuntimeError(
            "DASHSCOPE_API_KEY is not set. Configure it before running:\n"
            '  PowerShell : $env:DASHSCOPE_API_KEY = "sk-..."\n'
            '  bash       : export DASHSCOPE_API_KEY="sk-..."\n'
            "or put  DASHSCOPE_API_KEY=sk-...  in a .env file next to this script."
        )
    return OpenAI(api_key=api_key, base_url=BASE_URL)


def main(argv=None):
    """Standalone entry point: test the current generated navigation logic.

    NOTE: this file is named test_agent.py because the project brief requires
    it. Pytest would collect it as a test module (its import already works),
    and the helper below makes sure pytest performs no tests for it unless the
    orchestrator asks for the full pipeline.
    """
    argv = list(sys.argv[1:] if argv is None else argv)
    if "--pytest-collect-only" in argv:
        return 0

    requirements_path = os.path.join(HERE, "artifacts", "requirements.json")
    plan_path = os.path.join(HERE, "artifacts", "plan.json")
    navigation_path = (argv[0] if argv else os.path.join(GENERATED_DIR, "navigation_logic.py"))
    test_path = argv[1] if len(argv) > 1 else TEST_PATH

    requirements = {}
    plan = {}
    if os.path.exists(requirements_path):
        with open(requirements_path, "r", encoding="utf-8") as handle:
            requirements = json.load(handle)
    if os.path.exists(plan_path):
        with open(plan_path, "r", encoding="utf-8") as handle:
            plan = json.load(handle)

    with open(navigation_path, "r", encoding="utf-8") as handle:
        navigation_code = handle.read()

    outcome = generate_and_run_tests(
        requirements, plan, navigation_code, test_path=test_path
    )
    print(outcome["output"])
    print("Generated tests saved to %s" % outcome["test_path"])
    print("Test results: %s" % json.dumps(outcome["results"], indent=2))
    return 0 if outcome["results"]["status"] == "PASSED" else 1


if __name__ == "__main__":
    raise SystemExit(main())
